-- SELECT only. Run before dry-run/apply (also the before/after comparison for postcheck). Aggregates and hashes only; no row text, no ids.
-- 읽기 전용 역할에서 돈다: pg_catalog와 두 표의 줄 수만 읽는다.
-- 적용 전 기대: 새 기록 없음, 협업 함수 9개가 모두 있음(DEFINER), 두 표 있음·RLS 켜짐·FORCE 꺼짐, 새 정책 이름 없음, 소유자 확인 함수 있음.
-- 실행권 개수·줄 수·기존 정책·표 권한·트리거 해시는 기록만 하고, 실행권 개수 밖의 값은 사후 확인에서 같아야 한다.
-- expect: collaboration functions executable by anon or authenticated (count) = 기록
-- expect: app_workspace_members rows = 기록
-- expect: app_workspace_members owner rows = 기록
-- expect: app_invites rows = 기록
-- expect: existing policies hash (two tables) = 기록
-- expect: table grants and RLS hash (two tables) = 기록
-- expect: triggers hash (two tables) = 기록
-- expect: other collaboration-named definer functions callable by anon or authenticated (count) = 기록
select 'new migration absent' as item,case when not exists(select 1 from supabase_migrations.schema_migrations where version='20261102013000') then '예' else '아니오' end as value
union all select 'nine collaboration definer functions present',case when (select count(*) from pg_proc where oid in(to_regprocedure('public.app_create_invite(text,uuid,timestamptz)'),to_regprocedure('public.app_set_workspace_member_role(uuid,text)'),to_regprocedure('public.app_approve_access_request(uuid,text)'),to_regprocedure('public.app_reject_access_request(uuid)'),to_regprocedure('public.app_accept_invite(text)'),to_regprocedure('public.app_claim_owner(text,text)'),to_regprocedure('public.app_request_workspace_access(text)'),to_regprocedure('public.app_respond_project_invitation(uuid,boolean)'),to_regprocedure('public.app_join_default_team()')) and prosecdef)=9 then '예' else '아니오' end
union all select 'two tables present, RLS on, not forced',case when (select count(*) from pg_class where oid in(to_regclass('public.app_invites'),to_regclass('public.app_workspace_members')) and relrowsecurity and not relforcerowsecurity)=2 then '예' else '아니오' end
union all select 'new policies absent',case when not exists(select 1 from pg_policy where polrelid in(to_regclass('public.app_invites'),to_regclass('public.app_workspace_members')) and polname like 'collab\_lock\_%') then '예' else '아니오' end
union all select 'owner check function exists (definer)',case when exists(select 1 from pg_proc where oid=to_regprocedure('private.app_is_workspace_owner(uuid)') and prosecdef) then '예' else '아니오' end
union all select 'collaboration functions executable by anon or authenticated (count)',(select count(*)::text from pg_proc p where p.oid in(to_regprocedure('public.app_create_invite(text,uuid,timestamptz)'),to_regprocedure('public.app_set_workspace_member_role(uuid,text)'),to_regprocedure('public.app_approve_access_request(uuid,text)'),to_regprocedure('public.app_reject_access_request(uuid)'),to_regprocedure('public.app_accept_invite(text)'),to_regprocedure('public.app_claim_owner(text,text)'),to_regprocedure('public.app_request_workspace_access(text)'),to_regprocedure('public.app_respond_project_invitation(uuid,boolean)'),to_regprocedure('public.app_join_default_team()')) and (has_function_privilege('anon',p.oid,'execute') or has_function_privilege('authenticated',p.oid,'execute')))
union all select 'app_workspace_members rows',(select count(*)::text from public.app_workspace_members)
union all select 'app_workspace_members owner rows',(select count(*)::text from public.app_workspace_members where role='owner')
union all select 'app_invites rows',(select count(*)::text from public.app_invites)
union all select 'existing policies hash (two tables)',md5(coalesce((select string_agg(c.relname||':'||p.polname::text||':'||p.polcmd::text||':'||p.polpermissive::text||':'||p.polroles::text||':'||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||':'||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),''),',' order by c.relname,p.polname) from pg_policy p join pg_class c on c.oid=p.polrelid where p.polrelid in(to_regclass('public.app_invites'),to_regclass('public.app_workspace_members')) and p.polname not like 'collab\_lock\_%'),''))
union all select 'table grants and RLS hash (two tables)',md5(coalesce((select string_agg(c.relname||':'||c.relrowsecurity::text||':'||c.relforcerowsecurity::text||':'||coalesce(c.relacl::text,''),',' order by c.relname) from pg_class c where c.oid in(to_regclass('public.app_invites'),to_regclass('public.app_workspace_members'))),''))
union all select 'triggers hash (two tables)',md5(coalesce((select string_agg(c.relname||':'||t.tgname::text||':'||t.tgenabled::text,',' order by c.relname,t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid where t.tgrelid in(to_regclass('public.app_invites'),to_regclass('public.app_workspace_members')) and not t.tgisinternal),''))
union all select 'other collaboration-named definer functions callable by anon or authenticated (count)',(select count(*)::text from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('public','private') and p.prosecdef and p.proname ~ '(invite|invitation|member|role|attendee|assign|access_request|join|claim)' and p.oid not in(to_regprocedure('public.app_create_invite(text,uuid,timestamptz)'),to_regprocedure('public.app_set_workspace_member_role(uuid,text)'),to_regprocedure('public.app_approve_access_request(uuid,text)'),to_regprocedure('public.app_reject_access_request(uuid)'),to_regprocedure('public.app_accept_invite(text)'),to_regprocedure('public.app_claim_owner(text,text)'),to_regprocedure('public.app_request_workspace_access(text)'),to_regprocedure('public.app_respond_project_invitation(uuid,boolean)'),to_regprocedure('public.app_join_default_team()')) and (has_function_privilege('anon',p.oid,'execute') or has_function_privilege('authenticated',p.oid,'execute')));
